package chihalu.customstacklimit.mixin;

import chihalu.customstacklimit.StackLimitConfig;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.entity.player.PlayerInventory;
import net.minecraft.item.ItemStack;
import org.spongepowered.asm.mixin.Final;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

/**
 * PlayerInventoryの操作時にプレイヤーコンテキストを設定するMixin
 */
@Mixin(PlayerInventory.class)
public class PlayerInventoryMixin {

    @Shadow
    @Final
    public PlayerEntity player;

    /**
     * インベントリ操作時にプレイヤーコンテキストを設定
     */
    @Inject(method = "insertStack(ILnet/minecraft/item/ItemStack;)Z", at = @At("HEAD"))
    private void onInsertStack(int slot, ItemStack stack, CallbackInfoReturnable<Boolean> cir) {
        StackLimitConfig.setCurrentPlayer(player.getUuid());
    }

    @Inject(method = "insertStack(ILnet/minecraft/item/ItemStack;)Z", at = @At("RETURN"))
    private void onInsertStackReturn(int slot, ItemStack stack, CallbackInfoReturnable<Boolean> cir) {
        StackLimitConfig.clearCurrentPlayer();
    }

    @Inject(method = "insertStack(Lnet/minecraft/item/ItemStack;)Z", at = @At("HEAD"))
    private void onInsertStackNoSlot(ItemStack stack, CallbackInfoReturnable<Boolean> cir) {
        StackLimitConfig.setCurrentPlayer(player.getUuid());
    }

    @Inject(method = "insertStack(Lnet/minecraft/item/ItemStack;)Z", at = @At("RETURN"))
    private void onInsertStackNoSlotReturn(ItemStack stack, CallbackInfoReturnable<Boolean> cir) {
        StackLimitConfig.clearCurrentPlayer();
    }

    @Inject(method = "addStack(Lnet/minecraft/item/ItemStack;)I", at = @At("HEAD"))
    private void onAddStack(ItemStack stack, CallbackInfoReturnable<Integer> cir) {
        StackLimitConfig.setCurrentPlayer(player.getUuid());
    }

    @Inject(method = "addStack(Lnet/minecraft/item/ItemStack;)I", at = @At("RETURN"))
    private void onAddStackReturn(ItemStack stack, CallbackInfoReturnable<Integer> cir) {
        StackLimitConfig.clearCurrentPlayer();
    }
}
